import React, { useState, useContext } from "react";
import axios from "../api/axiosConfig";
import { useNavigate } from "react-router-dom";
import { Form, Button, Container, Alert } from "react-bootstrap";
import { AuthContext } from "../context/AuthContext";
import { toast } from "react-toastify";
import "./LoginPage.css";

function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();
  const { login } = useContext(AuthContext);

  const handleLogin = async (e) => {
    e.preventDefault();

    try {
      const response = await axios.post("/auth/login", { username, password });
      const { token, userId, username: fetchedUsername, role } = response.data;
      
      // Llama al método login del contexto
      login(token, userId, fetchedUsername, role);
      toast.success("Inicio de sesión exitoso!", {
        position: "top-right",
      });
      
      navigate("/");
    } catch (err) {
      setError("Usuario o contraseña incorrectos.");
      toast.error("Usuario o contraseña incorrectos.", {
        position: "top-right",
      });
    }
  };

  return (
    <Container className="login-container">
      <h2 className="text-center">Iniciar Sesión</h2>
      {error && <Alert variant="danger">{error}</Alert>}
      <Form onSubmit={handleLogin} className="mt-3">
        <Form.Group className="mb-3">
          <Form.Label>Nombre de Usuario</Form.Label>
          <Form.Control
            type="text"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Contraseña</Form.Label>
          <Form.Control
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </Form.Group>

        <Button variant="primary" type="submit" className="px-4 mx-auto d-block">
          Iniciar Sesión
        </Button>
      </Form>

      <p className="mt-3 text-center">
        ¿No tienes cuenta? <a href="/register">Regístrate aquí</a>
      </p>
      <p className="mt-1 text-center">
        ¿No recuerdas tu contraseña? <a href="/recover-password">Recupérala aquí</a>
      </p>
    </Container>
  );
}

export default LoginPage;