import axios from "axios";
import { toast } from "react-toastify";

// Configuración de Axios
const axiosInstance = axios.create({
  baseURL: "https://myvideogamelistbackend-cq70.onrender.com",
  withCredentials: false
});

// Interceptor para agregar el token JWT automáticamente
axiosInstance.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("token");
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Interceptor para manejar errores de autenticación (401 y 403)
axiosInstance.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response) {
      const status = error.response.status;

      if (status === 401) {
        // Error de autenticación (JWT expirado o inválido)
        console.warn("Token expirado o sesión no válida. Redirigiendo al login.");
        toast.error("Tu sesión ha expirado. Por favor, inicia sesión nuevamente.", {
          position: "top-right",
        });
        localStorage.removeItem("token");
        localStorage.removeItem("role");
        localStorage.removeItem("userId");
        setTimeout(() => {
          window.location.href = "/login";
        }, 1500);
      }
    }
    return Promise.reject(error);
  }
);

export default axiosInstance;
