import React, { useContext, useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Navbar, Container, Nav, Form, FormControl, NavDropdown } from "react-bootstrap";
import { FaUser, FaSignInAlt, FaSearch, FaUsers, FaGamepad, FaBars } from "react-icons/fa";
import { AuthContext } from "../context/AuthContext";
import logo from "../assets/logo.png";
import "./NavBar.css";

function NavBar() {
  const { user, logout } = useContext(AuthContext);
  const [searchQuery, setSearchQuery] = useState("");
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const navigate = useNavigate();

  // Escucha cambios de tamaño para activar el modo móvil
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 768);
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim() !== "") {
      navigate(`/search?query=${encodeURIComponent(searchQuery.trim())}&type=games`);
    }
  };

  return (
    <Navbar bg="light" expand="lg" className="py-3 shadow-sm">
      <Container className="d-flex align-items-center justify-content-between">
        {/* Logo */}
        <Navbar.Brand as={Link} to="/" className="d-flex align-items-center">
          <img src={logo} alt="Logo" className="navbar-logo" />
          MyVideogameList
        </Navbar.Brand>

        {/* Menú Hamburguesa */}
        <div className="menu-mobile ms-2">
          <NavDropdown
            title={<FaBars size={28} />}
            id="explore-dropdown"
            className={`d-flex align-items-center ${isMobile ? "dropstart" : ""}`}
          >
            <NavDropdown.Item as={Link} to="/top-100">Top 100 Mejores Juegos</NavDropdown.Item>
            <NavDropdown.Item as={Link} to="/upcoming">Próximos Lanzamientos</NavDropdown.Item>
            <NavDropdown.Item as={Link} to="/discover">Descubrir</NavDropdown.Item>
            <NavDropdown.Divider />
            <NavDropdown.Item as={Link} to="/stores">Tiendas Cercanas</NavDropdown.Item>
          </NavDropdown>
        </div>

        {/* Barra de Búsqueda */}
        <div className="search-bar-wrapper">
          <Form className="d-flex search-bar-centered" onSubmit={handleSearch} style={{ flexGrow: 1, maxWidth: "500px" }}>
            <FormControl
              type="search"
              placeholder="Buscar juegos..."
              className="me-2"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            <FaSearch style={{ cursor: "pointer" }} onClick={handleSearch} />
          </Form>
        </div>

        {/* Enlaces de Usuario */}
        <Nav className="ms-auto align-items-center">
          {user ? (
            <>
              {user.role === "ADMIN" && (
                <Link to="/admin/users" className="text-dark me-3">
                  <FaUsers size={24} /> Gestionar usuarios
                </Link>
              )}
              <div className="user-actions-responsive d-flex flex-wrap flex-md-nowrap justify-content-center gap-2">
                <Link to={`/profile/${user.userId}`} className="text-dark">
                  <FaUser size={24} /> Perfil
                </Link>
                <span className="text-danger" onClick={logout} style={{ cursor: "pointer" }}>
                  <FaSignInAlt size={24} /> Logout
                </span>
              </div>
            </>
          ) : (
            <div className="user-actions-responsive d-flex flex-wrap flex-md-nowrap justify-content-center gap-2">
              <Link to="/login" className="text-dark">
                <FaSignInAlt size={24} /> Login
              </Link>
              <Link to="/register" className="text-dark">
                <FaUser size={24} /> Register
              </Link>
            </div>
          )}
        </Nav>
      </Container>
    </Navbar>
  );
}

export default NavBar;