import React, { useEffect, useState } from "react";
import axios from "../api/axiosConfig";
import { Card, Container, Row, Col, Button, Form, Dropdown, Pagination } from "react-bootstrap";
import { Link, useNavigate } from "react-router-dom";
import "./UserManagementPage.css";

function UserManagementPage() {
  const [users, setUsers] = useState([]);
  const [comments, setComments] = useState([]);
  const [viewMode, setViewMode] = useState("Usuarios");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sortOrder, setSortOrder] = useState("desc");
  const [expandedComments, setExpandedComments] = useState({});
  const navigate = useNavigate();
  const itemsPerPage = 10;

  useEffect(() => {
    if (viewMode === "Usuarios") {
      fetchUsers();
    } else {
      fetchComments();
    }
  }, [viewMode, sortOrder]);

  const fetchUsers = async () => {
    try {
      const response = await axios.get("/api/users");
      setUsers(response.data);
      setTotalPages(Math.ceil(response.data.length / itemsPerPage));
    } catch (error) {
      console.error("Error al obtener usuarios:", error);
    }
  };

  const fetchComments = async () => {
    try {
      const response = await axios.get("/api/comments");
      const sortedComments = response.data.sort((a, b) => {
        const dateA = new Date(a.commentDate);
        const dateB = new Date(b.commentDate);
        return sortOrder === "asc" ? dateA - dateB : dateB - dateA;
      });
      setComments(sortedComments);
      console.log("Comentarios cargados:", sortedComments);
      setTotalPages(Math.ceil(sortedComments.length / itemsPerPage));
    } catch (error) {
      console.error("Error al obtener comentarios:", error);
    }
  };

  const handleDeleteComment = async (commentId) => {
    if (!window.confirm("¿Estás seguro de que deseas eliminar este comentario?")) return;
    try {
      await axios.delete(`/api/comments/${commentId}`);
      alert("Comentario eliminado correctamente.");
      fetchComments();
    } catch (error) {
      console.error("Error al eliminar comentario:", error);
      alert("Error al eliminar el comentario.");
    }
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const renderPagination = () => {
    const paginationItems = [];

    if (currentPage > 1) {
      paginationItems.push(
        <Pagination.First key="first" onClick={() => handlePageChange(1)} />,
        <Pagination.Prev key="prev" onClick={() => handlePageChange(currentPage - 1)} />
      );
    }

    if (currentPage > 2) {
      paginationItems.push(
        <Pagination.Item key={1} onClick={() => handlePageChange(1)}>1</Pagination.Item>
      );
    }

    if (currentPage > 3) {
      paginationItems.push(<Pagination.Ellipsis key="start-ellipsis" />);
    }

    paginationItems.push(
      <Pagination.Item key={currentPage} active>{currentPage}</Pagination.Item>
    );

    if (currentPage < totalPages - 2) {
      paginationItems.push(<Pagination.Ellipsis key="end-ellipsis" />);
    }

    if (currentPage < totalPages - 1) {
      paginationItems.push(
        <Pagination.Item key={totalPages} onClick={() => handlePageChange(totalPages)}>
          {totalPages}
        </Pagination.Item>
      );
    }

    if (currentPage < totalPages) {
      paginationItems.push(
        <Pagination.Next key="next" onClick={() => handlePageChange(currentPage + 1)} />,
        <Pagination.Last key="last" onClick={() => handlePageChange(totalPages)} />
      );
    }

    return paginationItems;
  };

  const toggleExpand = (id) => {
    setExpandedComments((prev) => ({
      ...prev,
      [id]: !prev[id],
    }));
  };

  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = viewMode === "Usuarios"
    ? users.slice(indexOfFirstItem, indexOfLastItem)
    : comments.slice(indexOfFirstItem, indexOfLastItem);

  return (
    <Container className="mt-4">
      <h2 className="mb-4 text-center">Gestión de Usuarios y Comentarios</h2>

      <Form.Select
        className="mb-3"
        value={viewMode}
        onChange={(e) => {
          setViewMode(e.target.value);
          setCurrentPage(1);
        }}
      >
        <option value="Usuarios">Usuarios</option>
        <option value="Comentarios">Comentarios</option>
      </Form.Select>

      {viewMode === "Comentarios" && (
        <div className="mb-3 d-flex justify-content-between align-items-center">
          <Form.Label>Ordenar por fecha:</Form.Label>
          <Form.Select
            value={sortOrder}
            onChange={(e) => setSortOrder(e.target.value)}
            style={{ width: "150px" }}
          >
            <option value="desc">Más recientes</option>
            <option value="asc">Más antiguos</option>
          </Form.Select>
        </div>
      )}

      {viewMode === "Usuarios" && (
        <div className="user-grid">
          {currentItems.map((user) => (
            <div className="user-card" key={user.id} onClick={() => navigate(`/profile/${user.id}`)} style={{ cursor: "pointer" }}>
              <img src={user.avatarUrl || "https://via.placeholder.com/80"} alt={`Avatar de ${user.username}`} className="user-avatar" />
              <div className="user-name">{user.username}</div>
              <div className="user-email">{user.email}</div>
              <div className="user-role">Rol: <strong>{user.roleName?.toUpperCase()}</strong></div>
            </div>
          ))}
        </div>
      )}

      {viewMode === "Comentarios" && (
        <Row className="g-4">
          {currentItems.length > 0 ? (
            currentItems.map((comment) => (
              <Col md={12} key={comment.id}>
                <Card
                  className="comment-card shadow-sm mb-3"
                  style={{ cursor: "pointer" }}
                  onClick={() => navigate(`/user/${comment.userId}/comments`)}
                >
                  <Card.Body className="d-flex align-items-start">
                    <img
                      src={comment.avatarUrl || "https://via.placeholder.com/50"}
                      alt="Avatar del usuario"
                      className="user-avatar me-3"
                      style={{ width: "50px", height: "50px", borderRadius: "50%" }}
                    />
                    <div className="flex-grow-1">
                      <h5 className="mb-0">{comment.username || "Usuario desconocido"}</h5>
                      <small className="text-muted">
                        Publicado: {new Date(comment.commentDate).toLocaleString()}
                        {comment.updatedAt && (
                          <> | Editado: {new Date(comment.updatedAt).toLocaleString()}</>
                        )}
                      </small>
                      <div className="mt-2 comment-text">
                        {comment.commentText.length > 200 && !expandedComments[comment.id]
                          ? `${comment.commentText.slice(0, 200)}...`
                          : comment.commentText}

                        {comment.commentText.length > 200 && (
                          <button
                            className="btn btn-link btn-sm ps-1"
                            style={{ textDecoration: "underline" }}
                            onClick={(e) => {
                              e.stopPropagation();
                              toggleExpand(comment.id);
                            }}
                          >
                            {expandedComments[comment.id] ? "Ver menos" : "Ver más"}
                          </button>
                        )}
                      </div>
                    </div>
                    <Button
                      variant="danger"
                      className="ms-2"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteComment(comment.id);
                      }}
                    >
                      🗑️
                    </Button>
                  </Card.Body>
                </Card>
              </Col>
            ))
          ) : (
            <p className="text-center">No hay comentarios disponibles.</p>
          )}
        </Row>
      )}

      <Pagination className="mt-4 justify-content-center">
        {renderPagination()}
      </Pagination>
    </Container>
  );
}

export default UserManagementPage;